///   3. Thread.ResetAbort() → check token.IsCancellationRequested and continue
///   4. volatile bool _running → CancellationToken controls the loop
///   5. Thread.Sleep(2000) → token.WaitHandle.WaitOne(2000) for cancellable wait
///   6. GetNextItem() must accept a CancellationToken so it can be interrupted
/// </summary>
public class BackgroundProcessor : IDisposable
{
    private Thread? _workerThread;
    private CancellationTokenSource? _cts;

    public void Start()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _workerThread = new Thread(() => ProcessLoop(token));
        _workerThread.IsBackground = true;
        _workerThread.Start();
    }

    private void ProcessLoop(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            try
            {
                // Pass the token so blocking calls can be interrupted.
                var item = GetNextItem(token);
                ProcessItem(item);
            }
            catch (OperationCanceledException) when (token.IsCancellationRequested)
            {
                // Cancellation requested — clean up partial work
                RollbackCurrentTransaction();
                // No need for ResetAbort; just let the loop condition exit naturally
            }
            finally
            {
                FlushBuffers();
            }
        }
    }

    public void Stop()
    {
        if (_cts is null || _workerThread is null)
            return;

        // Signal cooperative cancellation
        _cts.Cancel();

        // Wait up to 2 seconds for the thread to finish gracefully.
        // Unlike Thread.Abort, if the thread doesn't stop, we cannot
        // forcibly kill it — cooperative cancellation requires the
        // worker code to check the token.
        _workerThread.Join(TimeSpan.FromSeconds(2));
    }

    public void Dispose()
    {
        Stop();
        _cts?.Dispose();
        _cts = null;
    }

    // --- Stubs for compilation (replace with your real implementations) ---

    private object GetNextItem(CancellationToken token)
    {
        // PITFALL: If your original GetNextItem() blocked (e.g. on a
        // BlockingCollection or socket), you MUST pass the token so the
        // block can be interrupted. Examples:
        //
        //   BlockingCollection<T>.Take(token)
        //   await stream.ReadAsync(buffer, token)
        //   token.WaitHandle.WaitOne(timeout)
        //
        // Without this, Cancel() won't wake the blocked thread.
        token.ThrowIfCancellationRequested();
        return new object();
    }

    private void ProcessItem(object item) { }
    private void RollbackCurrentTransaction() { }
    private void FlushBuffers() { }
}

